using System.Text.Json;
using FluentAssertions;
using Sleeper.RosterReport.Recap;

namespace Sleeper.RosterReport.Tests;

/// <summary>
/// The data layer decides franchise-vs-owner continuity once, and every page on the site reads
/// that decision. Getting it wrong produces wrong all-time records everywhere at once, so the
/// generated file is asserted directly rather than trusted.
/// </summary>
public class LeagueDataTests
{
    [Theory]
    [InlineData("week-01", "weekly-recap", 1)]
    [InlineData("week-02-preview", "weekly-preview", 2)]
    [InlineData("week-07-what-to-watch", "monday-watch", 7)]
    [InlineData("preview", "season-preview", null)]
    [InlineData("season", "season-review", null)]
    public void ArticleKindsDistinguishPreviewFromResults(string name, string kind, int? week)
    {
        SiteDataBuilder.ClassifyArticle(name).Should().Be((kind, week));
    }

    [Fact]
    public void WeeklyEditionUsesCompleteResultsAndSeparateUpcomingFixtures()
    {
        var edition = SiteDataBuilder.LoadWeeklyEdition(Path.Combine(RecapPaths.WorkspaceRoot, "recaps"));
        edition.Should().NotBeNull();
        var snapshot = edition!.Value;
        var teams = snapshot.GetProperty("teams").EnumerateArray().ToList();
        var weeks = snapshot.GetProperty("weeks").EnumerateArray().ToList();
        weeks.Count.Should().Be(snapshot.GetProperty("completed_week").GetInt32());
        foreach (var week in weeks)
        {
            var games = week.GetProperty("games").EnumerateArray().ToList();
            var sides = games.SelectMany(game => new[] { game.GetProperty("home"), game.GetProperty("away") }).ToList();
            sides.Select(side => side.GetProperty("franchise_id").GetInt32()).Should()
                .BeEquivalentTo(teams.Select(team => team.GetProperty("franchise_id").GetInt32()));
            foreach (var game in games)
                game.GetProperty("margin").GetDecimal().Should().Be(Math.Abs(
                    game.GetProperty("home").GetProperty("points").GetDecimal()
                    - game.GetProperty("away").GetProperty("points").GetDecimal()));
        }

        teams.Sum(team => team.GetProperty("wins").GetInt32()).Should()
            .Be(teams.Sum(team => team.GetProperty("losses").GetInt32()));
        teams.Sum(team => team.GetProperty("points_for").GetDecimal()).Should()
            .Be(teams.Sum(team => team.GetProperty("points_against").GetDecimal()));
        snapshot.GetProperty("upcoming").EnumerateArray().All(game =>
            !game.TryGetProperty("points", out _)).Should().BeTrue();
        snapshot.TryGetProperty("champion", out _).Should().BeFalse();
    }

    [Theory]
    [InlineData(0, false)]
    [InlineData(6, false)]
    [InlineData(7, true)]
    [InlineData(10, true)]
    public void PublicWeeklyEditionNeverExposesRawNarrativeState(int level, bool expectsCues)
    {
        using var input = JsonDocument.Parse($$"""
            {
              "season": 2026,
              "completed_week": 4,
              "_narrative": { "sentience_level": {{level}} },
              "teams": []
            }
            """);

        var projected = SiteDataBuilder.BuildPublicWeeklyEdition(input.RootElement);
        var json = projected.ToJsonString();

        json.Should().NotContain("sentience_level");
        json.Should().NotContain("_narrative");
        projected.ContainsKey("editorial_cues").Should().Be(expectsCues);
        if (expectsCues)
            projected["editorial_cues"]!["generator"]!.GetValue<string>().Should().NotBeNullOrWhiteSpace();
    }

    private static readonly string DataPath =
        Path.Combine(RecapPaths.WorkspaceRoot, "site", "src", "data", "league.json");

    private static JsonElement Load()
    {
        File.Exists(DataPath).Should().BeTrue(
            $"site/src/data/league.json should be generated by `site-data` before the site is built (looked in {DataPath})");

        return JsonDocument.Parse(File.ReadAllText(DataPath)).RootElement.Clone();
    }

    [Fact]
    public void HeadToHeadIsSymmetric()
    {
        var root = Load();
        var pairs = root.GetProperty("records").GetProperty("head_to_head").EnumerateArray().ToList();
        pairs.Should().NotBeEmpty();

        foreach (var pair in pairs)
        {
            var owner = pair.GetProperty("owner_name").GetString();
            var opponent = pair.GetProperty("opponent_name").GetString();

            owner.Should().NotBe(opponent, "an owner cannot play himself");

            var mirror = pairs.SingleOrDefault(p =>
                p.GetProperty("owner_name").GetString() == opponent &&
                p.GetProperty("opponent_name").GetString() == owner);

            mirror.ValueKind.Should().NotBe(JsonValueKind.Undefined,
                $"every pairing needs both directions ({owner} vs {opponent})");

            mirror.GetProperty("wins").GetInt32().Should().Be(pair.GetProperty("losses").GetInt32());
            mirror.GetProperty("losses").GetInt32().Should().Be(pair.GetProperty("wins").GetInt32());
        }
    }

    [Fact]
    public void OwnerCareerTotalsMatchTheirSeasons()
    {
        var root = Load();

        foreach (var owner in root.GetProperty("owners").EnumerateArray())
        {
            var seasons = owner.GetProperty("seasons").EnumerateArray().ToList();
            var career = owner.GetProperty("career");

            career.GetProperty("seasons_played").GetInt32().Should().Be(seasons.Count);
            career.GetProperty("wins").GetInt32().Should()
                .Be(seasons.Sum(s => s.GetProperty("wins").GetInt32()));
            career.GetProperty("losses").GetInt32().Should()
                .Be(seasons.Sum(s => s.GetProperty("losses").GetInt32()));
        }
    }

    [Fact]
    public void CurrentEditionUpdatesOwnerCareersAndRecordBook()
    {
        var root = Load();
        var edition = root.GetProperty("current_edition");
        var currentSeason = edition.GetProperty("season").GetInt32();
        var completedWeek = edition.GetProperty("completed_week").GetInt32();
        var owners = root.GetProperty("owners").EnumerateArray().ToList();
        var allTime = root.GetProperty("records").GetProperty("all_time").EnumerateArray().ToList();

        foreach (var team in edition.GetProperty("teams").EnumerateArray())
        {
            var ownerName = team.GetProperty("owner_name").GetString();
            var owner = owners.Single(entry => entry.GetProperty("name").GetString() == ownerName);
            var ownerSeasons = owner.GetProperty("seasons").EnumerateArray().ToList();
            var current = ownerSeasons.Single(season => season.GetProperty("season").GetInt32() == currentSeason);
            current.GetProperty("wins").GetInt32().Should().Be(team.GetProperty("wins").GetInt32());
            current.GetProperty("losses").GetInt32().Should().Be(team.GetProperty("losses").GetInt32());
            current.GetProperty("points_for").GetDecimal().Should().Be(team.GetProperty("points_for").GetDecimal());

            var record = allTime.Single(entry => entry.GetProperty("owner_name").GetString() == ownerName);
            record.GetProperty("wins").GetInt32().Should()
                .Be(ownerSeasons.Sum(season => season.GetProperty("wins").GetInt32()));
            record.GetProperty("losses").GetInt32().Should()
                .Be(ownerSeasons.Sum(season => season.GetProperty("losses").GetInt32()));
        }

        root.GetProperty("records").GetProperty("notes").EnumerateArray()
            .Select(note => note.GetString())
            .Should().Contain(note => note!.Contains($"{currentSeason} through Week {completedWeek}", StringComparison.Ordinal));

        root.GetProperty("records").GetProperty("single_week_highs").EnumerateArray()
            .Should().Contain(entry => entry.GetProperty("season").GetInt32() == 2026
                && entry.GetProperty("week").GetInt32() == 5
                && entry.GetProperty("owner_name").GetString() == "Rob"
                && entry.GetProperty("points").GetDecimal() == 287.10m);

        var currentOnlyOwner = owners.Single(owner =>
        {
            var seasons = owner.GetProperty("seasons").EnumerateArray().ToList();
            return seasons.Count > 0
                && seasons.All(season => season.GetProperty("season").GetInt32() == currentSeason);
        });
        var currentOwnerName = currentOnlyOwner.GetProperty("name").GetString();
        root.GetProperty("records").GetProperty("head_to_head").EnumerateArray()
            .Where(entry => entry.GetProperty("owner_name").GetString() == currentOwnerName)
            .Sum(entry => entry.GetProperty("wins").GetInt32()
                + entry.GetProperty("losses").GetInt32()
                + entry.GetProperty("ties").GetInt32())
            .Should().Be(completedWeek);
    }

    /// <summary>
    /// A franchise that changes hands must not hand its completed history to the incoming owner,
    /// and the departing owner must not still read as active merely because he played the last
    /// completed season.
    /// </summary>
    [Fact]
    public void FranchiseHandoffPreservesOwnerRecordsAndActiveStatus()
    {
        var root = Load();
        var franchises = root.GetProperty("franchises").EnumerateArray().ToList();
        var owners = root.GetProperty("owners").EnumerateArray().ToList();

        var handedOff = franchises
            .Where(f => f.TryGetProperty("current_owner_name", out var current)
                && f.GetProperty("timeline").EnumerateArray().Any()
                && f.GetProperty("timeline").EnumerateArray().Last()
                    .GetProperty("owner_name").GetString() != current.GetString())
            .ToList();

        handedOff.Should().NotBeEmpty("the 2026 season includes an ownership change");

        foreach (var franchise in handedOff)
        {
            var incoming = franchise.GetProperty("current_owner_name").GetString();
            var departing = franchise.GetProperty("timeline").EnumerateArray().Last()
                .GetProperty("owner_name").GetString();

            var incomingOwner = owners.Single(o => o.GetProperty("name").GetString() == incoming);
            var departingOwner = owners.Single(o => o.GetProperty("name").GetString() == departing);

            incomingOwner.GetProperty("active").GetBoolean().Should().BeTrue();
            incomingOwner.GetProperty("seasons").EnumerateArray()
                .Should().ContainSingle(season => season.GetProperty("season").GetInt32()
                    == root.GetProperty("current_edition").GetProperty("season").GetInt32(),
                    "an incoming owner starts a new record in the active season instead of inheriting prior results");

            departingOwner.GetProperty("active").GetBoolean().Should().BeFalse(
                "a departed owner is not active even though he played the most recent completed season");
            departingOwner.GetProperty("career").GetProperty("seasons_played").GetInt32().Should()
                .BeGreaterThan(0, "a departed owner keeps the record he earned");

            franchise.GetProperty("owner_history").EnumerateArray()
                .Select(o => o.GetString())
                .Should().ContainInOrder(departing, incoming);
        }
    }

    [Fact]
    public void EverySeasonStandingsRowHasAFranchiseAndOwner()
    {
        var root = Load();
        var seasons = root.GetProperty("seasons").EnumerateArray().ToList();
        seasons.Should().NotBeEmpty();

        foreach (var season in seasons)
        {
            var standings = season.GetProperty("standings").EnumerateArray().ToList();
            standings.Should().NotBeEmpty();

            foreach (var row in standings)
            {
                row.GetProperty("franchise_id").GetInt32().Should().BeGreaterThan(0);
                row.GetProperty("owner_name").GetString().Should().NotBeNullOrWhiteSpace();
                row.GetProperty("owner_name").GetString().Should().NotStartWith("Roster ",
                    "an unresolved owner means the lore join key is broken");
            }
        }
    }
}
